mkdir -p /tmp/scratch && cat > /tmp/scratch/Check.java <<'EOF'
import java.util.*;

public class Check {
    static int failures = 0;

    static void expect(String name, List<Integer> coins, int total, Object expected) {
        ChangeCalculator c = new ChangeCalculator(coins);
        try {
            List<Integer> got = c.computeMostEfficientChange(total);
            if (expected instanceof String) {
                fail(name, "expected exception " + expected + " but got " + got);
            } else if (!got.equals(expected)) {
                fail(name, "expected " + expected + " but got " + got);
            } else {
                System.out.println("PASS " + name + " -> " + got);
            }
        } catch (IllegalArgumentException e) {
            if (expected instanceof String && ((String) expected).equals(e.getMessage())) {
                System.out.println("PASS " + name + " -> threw: " + e.getMessage());
            } else {
                fail(name, "unexpected exception: " + e.getMessage());
            }
        }
    }

    static void fail(String name, String msg) {
        failures++;
        System.out.println("FAIL " + name + ": " + msg);
    }

    public static void main(String[] a) {
        expect("1cent", Arrays.asList(1,5,10,25), 1, Arrays.asList(1));
        expect("singleCoin", Arrays.asList(1,5,10,25,100), 25, Arrays.asList(25));
        expect("multiple", Arrays.asList(1,5,10,25,100), 15, Arrays.asList(5,10));
        expect("lilliputian", Arrays.asList(1,4,15,20,50), 23, Arrays.asList(4,4,15));
        expect("lowerElbonian", Arrays.asList(1,5,10,21,25), 63, Arrays.asList(21,21,21));
        expect("large", Arrays.asList(1,2,5,10,20,50,100), 999,
               Arrays.asList(2,2,5,20,20,50,100,100,100,100,100,100,100,100,100));
        expect("noUnit", Arrays.asList(2,5,10,20,50), 21, Arrays.asList(2,2,2,5,10));
        expect("noUnit2", Arrays.asList(4,5), 27, Arrays.asList(4,4,4,5,5,5));
        expect("greedyNotOptimal", Arrays.asList(1,10,11), 20, Arrays.asList(10,10));
        expect("zero", Arrays.asList(1,5,10,21,25), 0, Collections.<Integer>emptyList());
        expect("lessThanSmallest", Arrays.asList(5,10), 3,
               "The total 3 cannot be represented in the given currency.");
        expect("largerUnrepresentable", Arrays.asList(5,10), 94,
               "The total 94 cannot be represented in the given currency.");
        expect("negative", Arrays.asList(1,2,5), -5, "Negative totals are not allowed.");
        // extra semantic checks
        expect("emptyCoinsZero", Collections.<Integer>emptyList(), 0, Collections.<Integer>emptyList());
        expect("emptyCoinsPositive", Collections.<Integer>emptyList(), 5,
               "The total 5 cannot be represented in the given currency.");
        expect("unorderedCoins", Arrays.asList(25,10,5,1), 40, Arrays.asList(5,10,25));
        expect("largeAmountPerf", Arrays.asList(1,2,5,10,20,50,100), 10000, null) ;
        System.out.println(failures == 0 ? "ALL OK" : failures + " FAILURES");
    }
}
