            if (expected instanceof String) {
                fail(name, "expected exception " + expected + " but got " + got);
            } else if (!got.equals(expected)) {
                fail(name, "expected " + expected + " but got " + got);
            } else {
                System.out.println("PASS " + name + " -> " + got);
            }
        } catch (IllegalArgumentException e) {
            if (expected instanceof String && ((String) expected).equals(e.getMessage())) {
                System.out.println("PASS " + name + " -> threw: " + e.getMessage());
            } else {
                fail(name, "unexpected exception: " + e.getMessage());
            }
